function updateExternal(){const source=document.getElementById('external-text'),output=document.getElementById('external-output');if(!source||!output)return;ext.externalText=source.value;ext.externalBase=timeToSec(document.getElementById('external-base').value);ext.externalSeconds=timeToSec(document.getElementById('external-carry').value);if(!(ext.externalBase>0&&ext.externalSeconds>0&&ext.externalSeconds<=ext.externalBase)){output.textContent='입력한 시간을 확인하세요.';return;}output.textContent=adjustedWithBase(source.value,ext.externalSeconds,ext.externalBase);}
