function saveCompleteMember(form){const fd=new FormData(form),id=String(fd.get('memberId')),name=String(fd.get('name')).trim(),from=Number(fd.get('fromDay')),to=Number(fd.get('toDay'));if(!name||data.members.some(m=>m.id!==id&&m.name===name)){toast('닉네임이 비었거나 중복됩니다.');return;}if(!(from>=1&&to>=from&&to<=data.rules.days)){toast('참가 일차 범위를 확인하세요.');return;}const periods=[];for(let i=0;fd.has('period-from-'+i);i++){const start=fd.get('period-from-'+i),end=fd.get('period-to-'+i);if(start&&end&&end<start){toast('소속 기간의 순서를 확인하세요.');return;}if(start)periods.push({from:start,to:end||null});}checkpoint();let m=data.members.find(m=>m.id===id);const values={name,uid:String(fd.get('uid')),status:String(fd.get('status')),joined:String(fd.get('joined')),periods,note:String(fd.get('note')),left:periods.at(-1)?.to?periods.at(-1).to+'-01':''};if(m){const previous=m.name;Object.assign(m,values);if(previous!==name)m.aliases=[...new Set([...(m.aliases||[]),previous])];}else{m={id:uid(),...values};data.members.push(m);}data.memberships[m.id]={from,to};persist();closeDrawer();render();toast('클랜원 저장',true);}
