function readCoefficientDraft(form,fd,id){
 const input=form.querySelector?.(`[name="boss-contribution-${id}"]`);
 if(input&&input.dataset.changed!=='true'&&input.value===input.dataset.display)return Number(input.dataset.exact);
 return Number(fd.get('boss-contribution-'+id));
}
function collectRulesDraft(form){if(!ext.bossDraft)ext.bossDraft={rules:structuredClone(data.rules),bosses:structuredClone(data.bossSettings)};const fd=new FormData(form),r=ext.bossDraft.rules;r.startDate=String(fd.get('startDate'));for(const key of ['days','daily','startStage','samples'])r[key]=Number(fd.get(key));r.factor=Number(fd.get('factor'))/100;r.baseline=Number(fd.get('baseline'));r.stage3Mode=String(fd.get('stage3Mode'));r.autoContribution=fd.has('autoContribution');r.carryVisible=fd.has('carryVisible');for(const l of r.levels)l.count=Number(fd.get('count-'+l.stage));for(const b of ext.bossDraft.bosses){b.name=String(fd.get('boss-name-'+b.id));b.portraitKey=String(fd.get('boss-art-'+b.id)||'none');if(b.portraitKey!=='future')delete b.portraitUrl;b.hp[ext.configStage]=Number(fd.get('boss-hp-'+b.id));b.game[ext.configStage]=Number(fd.get('boss-game-'+b.id));b.contribution[ext.configStage]=readCoefficientDraft(form,fd,b.id);}}
document.addEventListener('input',event=>{if(event.target.name?.startsWith('boss-contribution-'))event.target.dataset.changed='true';});
