function settingsData(){return `<section class="settings-sheet"><div class="sheet-heading"><h2>월별 관리</h2>${simpleButton('다음 달 만들기','v2-new-month','','primary')}</div>${rowTable(['월','기록','택틱','열기'],Object.keys(data.seasons).sort().reverse().map(key=>{const s=key===ui.month?data:data.seasons[key];return `<tr><td>${key.replace('-','.')}</td><td>${s.logs.length}건</td><td>${s.tactics.filter(t=>!t.deletedAt).length}개</td><td>${simpleButton('열기','v2-switch-month',key,'quiet')}</td></tr>`;}))}<div class="setting-row"><div><h3>전체 백업</h3><p>모든 월의 기록·택틱·설정·클랜원</p></div>${simpleButton('JSON 저장','export-json')}</div><div class="setting-row"><div><h3>선택한 월 백업</h3><p>${ui.month.replace('-','.')}</p></div>${simpleButton('JSON 저장','v2-export-month')}</div><div class="setting-row"><div><h3>백업 복원</h3></div><input type="file" accept=".json" data-input="v2-restore" aria-label="백업 JSON 선택"></div><div class="setting-row"><div><h3>시제품 초기화</h3><p>불러온 10월 자료로 되돌립니다.</p></div>${simpleButton('초기화','v2-reset-confirm','','danger')}</div><p class="field-help">이 시제품의 수정 내용은 이 브라우저에 저장됩니다. 기존 사이트와 동기화하지 않습니다.</p></section>`;}
